def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    def tokenize(s: str):
        toks = []
        i = 0
        n = len(s)
        while i < n:
            ch = s[i]
            if ch.isspace():
                i += 1
                continue
            if ch.isdigit():
                j = i + 1
                while j < n and s[j].isdigit():
                    j += 1
                toks.append(("NUM", int(s[i:j])))
                i = j
                continue
            if ch.isalpha():
                if i + 1 < n and s[i + 1].isdigit():
                    j = i + 1
                    while j < n and s[j].isdigit():
                        j += 1
                    toks.append(("CELL", ch.upper() + s[i + 1:j]))
                    i = j
                else:
                    j = i + 1
                    while j < n and s[j].isalpha():
                        j += 1
                    toks.append(("IDENT", s[i:j].upper()))
                    i = j
                continue
            if i + 1 < n and s[i:i + 2] in ("<>", "<=", ">="):
                toks.append(("CMP", s[i:i + 2]))
                i += 2
                continue
            if ch in "=<>":
                toks.append(("CMP", ch))
                i += 1
                continue
            if ch in "+-*/":
                toks.append(("OP", ch))
                i += 1
                continue
            if ch == "(":
                toks.append(("LP",))
                i += 1
                continue
            if ch == ")":
                toks.append(("RP",))
                i += 1
                continue
            if ch == ",":
                toks.append(("COMMA",))
                i += 1
                continue
            if ch == ":":
                toks.append(("COLON",))
                i += 1
                continue
            raise ValueError(ch)
        toks.append(("EOF",))
        return toks

    def parse(s: str):
        toks = tokenize(s)
        p = 0

        def peek(k=0):
            j = p + k
            return toks[j] if j < len(toks) else ("EOF",)

        def consume():
            nonlocal p
            t = peek()
            p += 1
            return t

        def parse_expr():
            node = parse_term()
            while peek()[0] == "OP" and peek()[1] in "+-":
                op = consume()[1]
                node = ("bin", op, node, parse_term())
            return node

        def parse_term():
            node = parse_factor()
            while peek()[0] == "OP" and peek()[1] in "*/":
                op = consume()[1]
                node = ("bin", op, node, parse_factor())
            return node

        def parse_factor():
            if peek()[0] == "OP" and peek()[1] == "-":
                consume()
                return ("neg", parse_factor())
            return parse_atom()

        def parse_atom():
            t = peek()
            if t[0] == "NUM":
                consume()
                return ("num", t[1])
            if t[0] == "CELL":
                consume()
                return ("cell", t[1])
            if t[0] == "LP":
                consume()
                node = parse_expr()
                consume()
                return node
            consume()
            name = t[1]
            consume()
            if name == "IF":
                left = parse_expr()
                op = consume()[1]
                right = parse_expr()
                consume()
                then_b = parse_expr()
                consume()
                else_b = parse_expr()
                consume()
                return ("if", left, op, right, then_b, else_b)
            args = [parse_arg()]
            while peek()[0] == "COMMA":
                consume()
                args.append(parse_arg())
            consume()
            return ("agg", name, args)

        def parse_arg():
            if peek()[0] == "CELL" and peek(1)[0] == "COLON":
                a = consume()[1]
                consume()
                b = consume()[1]
                return ("range", a, b)
            return parse_expr()

        return parse_expr()

    def rectangle(a: str, b: str):
        ca, ra = a[0], int(a[1:])
        cb, rb = b[0], int(b[1:])
        clo, chi = (ca, cb) if ca <= cb else (cb, ca)
        rlo, rhi = (ra, rb) if ra <= rb else (rb, ra)
        names = []
        for r in range(rlo, rhi + 1):
            for c in range(ord(clo), ord(chi) + 1):
                name = chr(c) + str(r)
                if name in cells:
                    names.append(name)
        return names

    def apply_op(op, left, right):
        if op == "+":
            return left + right
        if op == "-":
            return left - right
        if op == "*":
            return left * right
        if right == 0:
            return "#DIV/0!"
        neg = (left < 0) != (right < 0)
        q = abs(left) // abs(right)
        return -q if neg else q

    def compare(op, left, right):
        if op == "=":
            return left == right
        if op == "<>":
            return left != right
        if op == "<":
            return left < right
        if op == "<=":
            return left <= right
        if op == ">":
            return left > right
        return left >= right

    def finish_agg(func, acc):
        if func == "SUM":
            return sum(acc)
        if not acc:
            return 0
        if func == "MIN":
            return min(acc)
        return max(acc)

    asts = {}
    for name, content in cells.items():
        text = content.strip()
        if text.startswith("="):
            asts[name] = parse(text[1:])
        else:
            asts[name] = ("num", int(text))

    memo = {}
    visiting = set()

    def compute(start):
        if start in memo:
            return memo[start]
        work = [("node", ("cell", start))]
        results = []
        while work:
            item = work.pop()
            kind = item[0]
            if kind == "node":
                node = item[1]
                typ = node[0]
                if typ == "num":
                    results.append(node[1])
                elif typ == "cell":
                    ref = node[1]
                    if ref in memo:
                        results.append(memo[ref])
                    elif ref not in cells:
                        results.append(0)
                    elif ref in visiting:
                        results.append("#CYCLE!")
                    else:
                        visiting.add(ref)
                        work.append(("finish_cell", ref))
                        work.append(("node", asts[ref]))
                elif typ == "neg":
                    work.append(("neg",))
                    work.append(("node", node[1]))
                elif typ == "bin":
                    work.append(("bin_r", node[1], node[3]))
                    work.append(("node", node[2]))
                elif typ == "if":
                    work.append(("if_r", node[2], node[3], node[4], node[5]))
                    work.append(("node", node[1]))
                else:
                    work.append(("agg", node[1], node[2], 0, []))
            elif kind == "finish_cell":
                ref = item[1]
                val = results.pop()
                visiting.remove(ref)
                memo[ref] = val
                results.append(val)
            elif kind == "neg":
                val = results.pop()
                results.append(val if isinstance(val, str) else -val)
            elif kind == "bin_r":
                op, right = item[1], item[2]
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    work.append(("bin", op, left))
                    work.append(("node", right))
            elif kind == "bin":
                op, left = item[1], item[2]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                else:
                    results.append(apply_op(op, left, right))
            elif kind == "if_r":
                op, right, then_b, else_b = item[1], item[2], item[3], item[4]
                left = results.pop()
                if isinstance(left, str):
                    results.append(left)
                else:
                    work.append(("if_b", op, left, then_b, else_b))
                    work.append(("node", right))
            elif kind == "if_b":
                op, left, then_b, else_b = item[1], item[2], item[3], item[4]
                right = results.pop()
                if isinstance(right, str):
                    results.append(right)
                else:
                    chosen = then_b if compare(op, left, right) else else_b
                    work.append(("node", chosen))
            elif kind == "agg":
                func, args, idx, acc = item[1], item[2], item[3], item[4]
                if idx >= len(args):
                    results.append(finish_agg(func, acc))
                else:
                    arg = args[idx]
                    if arg[0] == "range":
                        names = rectangle(arg[1], arg[2])
                        work.append(("range", func, args, idx, acc, names, 0))
                    else:
                        work.append(("agg_v", func, args, idx, acc))
                        work.append(("node", arg))
            elif kind == "agg_v":
                func, args, idx, acc = item[1], item[2], item[3], item[4]
                val = results.pop()
                if isinstance(val, str):
                    results.append(val)
                else:
                    acc.append(val)
                    work.append(("agg", func, args, idx + 1, acc))
            elif kind == "range":
                func, args, idx, acc, names, j = (
                    item[1], item[2], item[3], item[4], item[5], item[6]
                )
                if j >= len(names):
                    work.append(("agg", func, args, idx + 1, acc))
                else:
                    work.append(("range_v", func, args, idx, acc, names, j))
                    work.append(("node", ("cell", names[j])))
            else:
                func, args, idx, acc, names, j = (
                    item[1], item[2], item[3], item[4], item[5], item[6]
                )
                val = results.pop()
                if isinstance(val, str):
                    results.append(val)
                else:
                    acc.append(val)
                    work.append(("range", func, args, idx, acc, names, j + 1))
        return memo[start]

    return {name: compute(name) for name in cells}
